class Bad {
    companion object {
        var count: Int = 0 // bad: mutable static field, not thread-safe
    }
}

object Counter {
    var count: Int = 0 // bad
}

class Good {
    companion object {
        val MAX: Int = 100 // ok: immutable
    }
}

class GoodVolatile {
    companion object {
        @Volatile
        var running: Boolean = false // ok: volatile
    }
}

class GoodLocal {
    fun doWork() {
        var count = 0 // ok: local variable
        count++
    }
}
